'use strict';
importScripts('offline-assets.js');
const CACHE='toolbox-app-'+toolboxOfflineAssets.version,EXTRA='toolbox-study-'+toolboxOfflineAssets.studyVersion,base=new URL('./',self.location.href),path=f=>new URL(f,base).href;
const core=new Set(toolboxOfflineAssets.core.map(path)),extra=new Set(toolboxOfflineAssets.extra.map(path));
function canonical(url){const u=new URL(url);u.hash='';u.search='';return u.href}
self.addEventListener('install',e=>e.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll([...core].map(url=>new Request(url,{cache:'reload'})))})()));
self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const key of await caches.keys())if((key.startsWith('toolbox-app-')||key.startsWith('toolbox-study-'))&&![CACHE,EXTRA].includes(key))await caches.delete(key);await self.clients.claim()})()));
async function cachedStatic(request,url){const cache=await caches.open(extra.has(url)?EXTRA:CACHE),saved=await cache.match(url);if(saved){const range=request.headers.get('range');if(range&&url.endsWith('.pdf')){const data=await saved.arrayBuffer(),m=/^bytes=(\d+)-(\d*)$/.exec(range);if(!m)return new Response(null,{status:416});const start=Number(m[1]),end=Math.min(m[2]?Number(m[2]):data.byteLength-1,data.byteLength-1);if(start>end||start>=data.byteLength)return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+data.byteLength}});return new Response(data.slice(start,end+1),{status:206,headers:{'Content-Type':'application/pdf','Accept-Ranges':'bytes','Content-Range':`bytes ${start}-${end}/${data.byteLength}`,'Content-Length':String(end-start+1)}})}return saved}const response=await fetch(request);if(response.ok&&response.status===200&&!request.headers.has('range'))await cache.put(url,response.clone());return response}
self.addEventListener('fetch',e=>{const r=e.request,u=new URL(r.url);if(r.method!=='GET'||u.origin!==base.origin)return;const url=canonical(r.url);if(r.mode==='navigate'&&(u.pathname===base.pathname||url===path('index.html'))){e.respondWith((async()=>{const c=await caches.open(CACHE);return await c.match(path('index.html'))||fetch(r)})());return}if(core.has(url)||extra.has(url))e.respondWith(cachedStatic(r,url))});
let downloading=null;
self.addEventListener('message',e=>{if(e.data?.type!=='DOWNLOAD_ALL'||!e.ports[0])return;const port=e.ports[0];if(downloading){port.postMessage({type:'error',message:'An offline download is already running. Wait, then retry if needed.'});return}downloading=(async()=>{try{const cache=await caches.open(EXTRA);let done=0;const list=[...extra];for(const url of list){if(!await cache.match(url)){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);try{const r=await fetch(url,{signal:controller.signal});if(!r.ok||r.status!==200)throw Error('Download interrupted. Reconnect and press Download again to resume.');await cache.put(url,r)}finally{clearTimeout(timer)}}port.postMessage({type:'progress',done:++done,total:list.length})}port.postMessage({type:'complete'})}catch(error){port.postMessage({type:'error',message:error.name==='AbortError'?'Download timed out. Reconnect and press Download again to resume.':error.message||'Offline download failed. Check device space and connection.'})}finally{downloading=null;port.close()}})();e.waitUntil(downloading)});
